import {DAYS,mission,missionProgress,rewardFor,settleDay,categoryResults} from './campaign.mjs?v=chair-shortcut-31';
const $=s=>document.querySelector(s),n=v=>Math.round(v??0),pct=v=>v==null?'—':n(v)+'%',money=v=>(v<0?'−':'')+'$'+Math.abs(n(v)),esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const bars=types=>categoryResults(types).map(t=>`<div class="satisfaction-row"><span>${t.name}</span><div class="satisfaction-track"><i style="width:${t.satisfaction??0}%;background-size:${t.satisfaction?10000/t.satisfaction:100}% 100%"></i></div><b>${pct(t.satisfaction)}</b></div>`).join('');
export function createDayUI(state,actions){
 const modal=$('#dayModal');let speed=1,paused=false,inspecting=false,lastSim=null,planningMetrics=null,planningKey='';
 const api={inspect:on=>{inspecting=on;refresh()},pause:()=>{paused=true;refresh()},refresh,requestRun,completed,live,restore,get speed(){return state.phase==='intervene'||paused||inspecting?0:speed},setSpeed:value=>{speed=[1,2,3].includes(+value)?+value:1;refresh()},get paused(){return paused}};
 function changed(){state.opened=!['design','renovate','adjust','intervene','day-running'].includes(state.phase);actions.changed();refresh()}
 function show(html){modal.innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0}
 modal.addEventListener('cancel',e=>{e.preventDefault();modal.close()});
 function showMission(){const m=state.dayNumber===1?{...mission(state),name:'Grand Reopening',hint:'Bring your rundown café back to life. Choose your repairs and furniture, then open whenever you’re ready.'}:mission(state),icons=['☕','🌿','📚','🔥'];show(`<div class="mission-intro"><div class="mission-ribbon">YOUR CAFÉ · YOUR CALL</div><div class="mission-medallion">${icons[state.dayNumber-1]}</div><span class="eyebrow">DAY ${state.dayNumber} OF ${DAYS.length}</span><h1>${esc(m.name)}</h1>${state.dayNumber===1?'<h2>Welcome, Floor Manager!</h2>':''}<p class="mission-hook">${esc(m.hint)}</p><p>Choose what matters. Watch your customers. Try a different approach.</p><section class="welcome-missions"><h3>Your missions</h3><ul>${m.goals.map(([,target,label])=>`<li>${esc(label)}</li>`).join('')}</ul></section><button id="beginPlanning" class="green-btn">Make it yours →</button></div>`);$('#beginPlanning').onclick=()=>{state.welcomeSeen=true;state.missionSeen=state.dayNumber;modal.close();actions.save();actions.prepare?.()}}
 function refresh(){
  const phase=state.phase,running=['day-running','intervene'].includes(phase),planning=['design','renovate','adjust'].includes(phase),m=mission(state);
  document.body.dataset.service=phase==='day-running'?'on':'';$('#slotNumber').textContent='DAY '+state.dayNumber+' / '+DAYS.length+(state.attempt>1?' · TRY '+state.attempt:'');$('#slotName').textContent=m.name;
  $('#pauseSim').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation');$('#quizProgress').textContent=phase==='intervene'?'Service paused. Move unoccupied furniture, then continue.':planning?m.hint:'';
  $('#changeBudget').hidden=true;$('#simControls').hidden=!running;$('#livePanel').hidden=!running||phase==='intervene';$('#resultsButton').hidden=!['day-report','campaign-complete'].includes(phase);$('#open').hidden=!(planning||phase==='intervene');$('#open').disabled=planning&&!!openingBlocker(state);$('#open').title=openingBlocker(state)||'Open café';$('#open').textContent=phase==='intervene'?'▶':'▶ Open';$('#simTime').hidden=!running;$('#streakCorner').hidden=!running;
  $('#interveneSim').hidden=!running;$('#interveneSim').textContent=phase==='intervene'?'▶':'✎';$('#pauseSim').textContent=paused?'▶':'Ⅱ';$('#pauseSim').disabled=phase==='intervene';
  for(const b of document.querySelectorAll('[data-speed]'))b.setAttribute('aria-pressed',+b.dataset.speed===speed);
  const r=lastSim&&running?lastSim.results():phase==='day-report'?state.reports.current:phase==='campaign-complete'?state.campaignHistory.at(-1)?.report:null;
  let display=r;if(planning){const key=JSON.stringify([state.objects,state.lights,state.atmosphere,state.renovations,state.blinds]);if(key!==planningKey){planningKey=key;planningMetrics=layoutMissionStats(new CafeSimulation({...cafeSnapshot(state),baselineLayout:undefined},'day'));}display=planningMetrics;}renderGoals(display);
  $('#dayDots').innerHTML=DAYS.map((d,i)=>`<span title="Day ${i+1}: ${d.name}" class="${i+1===state.dayNumber?'current':i+1<state.dayNumber?'done':''}">${i+1<state.dayNumber?'✓':i+1}</span>`).join('');
  $('#layoutPreview').hidden=!planning&&phase!=='intervene';
 }
 function renderGoals(r){const preparing=!cleanupReady(state)&&['design','renovate','adjust'].includes(state.phase),goals=preparing?cleanupGoals(state).map(g=>({...g,target:1,value:g.met?1:0})):missionProgress(state,r),met=goals.filter(g=>g.met).length;$('#missionSummary').textContent=`${met} / ${goals.length} · ${preparing?'Restore before opening':'Missions'}`;
 $('#dailyGoals').innerHTML=goals.map(g=>`<div class="mission-goal ${g.met?'met':''}"><span>${g.met?'✓':'○'} ${esc(g.label)}</span><b>${g.pending?'…':g.key==='profit'?money(g.value)+' / '+money(g.target):g.key==='satisfaction'&&state.dayNumber===1?(Math.round(g.value*10)/10)+'%':(g.key.includes('Stars')||g.key==='stars'?Math.min(g.value,g.target).toFixed(1):n(Math.min(g.value,g.target)))+' / '+g.target}</b><progress max="${g.target}" value="${g.pending?0:Math.min(g.target,g.value)}" title="${g.pending?'Waiting for 3 completed visits':g.key==='completedRequests'?'Each request counts once. Both sides of a conflict must be satisfied.':g.key==='ergonomicRescues'?'Plan a better seat or fix discomfort: a guest must reach 3.25 stars. Planning improvements need 5 comfortable seated minutes. Each guest counts once.':esc(g.label)}" aria-label="${esc(g.label)}"></progress></div>`).join('');
 if(state.dayNumber>=2&&r?.areas){$('#dailyGoals').innerHTML+=`<div class="area-status">${[['social','Social corner'],['focus','Focus space'],['cozy','Cozy lounge']].map(([k,label])=>`<span>${r.areas[k].length?'✓':'○'} ${label}</span>`).join('')}</div>`;}if($('#catalogMissionGoals'))$('#catalogMissionGoals').innerHTML=$('#dailyGoals').innerHTML;
 $('#missionHistory').innerHTML=(state.campaignHistory||[]).map(h=>`<button data-replay="${h.day}" ${state.phase==='day-running'||state.phase==='intervene'||state.practiceReturn?'disabled':''}>Day ${h.day}: ${h.goals.filter(g=>g.met).length}/${h.goals.length} standards · Replay</button>`).join('');
 for(const b of document.querySelectorAll('[data-replay]'))b.onclick=()=>{const h=state.campaignHistory.find(h=>h.day===+b.dataset.replay);if(!h?.start){actions.toast('Replay is available for shifts completed after this update.');return}const saved=JSON.parse(JSON.stringify(state));for(const k of Object.keys(state))delete state[k];Object.assign(state,JSON.parse(JSON.stringify(h.start)));state.practiceReturn=saved;state.dayNumber=h.day;state.phase='adjust';state.reports={};state.attemptStart=null;lastSim=null;actions.renovate();changed();actions.toast('Practice replay: improve your record. Your current café and budget stay safe.');};
 }
 function requestRun(){
  if(state.phase==='intervene'){actions.cancel();state.phase='day-running';paused=false;changed();actions.resume?.();return}
  if(!['design','renovate','adjust'].includes(state.phase))return;const blocker=openingBlocker(state);if(blocker){actions.toast(blocker);actions.prepare?.();return;}state.openingRepairBudget=0;
  actions.cancel();state.attemptStart=JSON.parse(JSON.stringify({...state,practiceReturn:undefined,attemptStart:undefined}));state.phase='day-running';state.runSnapshot=cafeSnapshot(state);state.runElapsed=0;state.liveCredited=0;state.shiftHintStart=state.hintSpent||0;api.lastBreak=null;$('#streakNotice').hidden=true;state.interventions=[];paused=false;lastSim=null;modal.close();changed();actions.begin('day',state.runSnapshot);
 }
 function completed(report){creditSales(report);
  state.reports.first||=report;state.reports.current=report;state.phase='day-report';state.runElapsed=0;state.runSnapshot=null;lastSim=null;inspecting=false;changed();renderReport();
 }
 function renderReport(){
  const r=state.reports.current;if(!r)return;if(r.inspection){show(`<div class="mission-intro"><div class="mission-medallion">🔑</div><h1>Ready to reopen!</h1><p>Open with the layout you chose.</p><p>Tomorrow your first customers will show you what works.</p><button id="acceptInspection" class="green-btn">Day 2 · Make Them Stay →</button></div>`);$('#acceptInspection').onclick=()=>{settleDay(state);modal.close();actions.renovate();changed();showMission()};return}const old=state.reports.previous,goals=missionProgress(state,r),reward=rewardFor(state,r);
  const previous=old||state.campaignHistory.at(-1)?.report;
  show(`<div class="report-head"><span class="eyebrow">SHIFT ${state.dayNumber} COMPLETE</span><h1>Your café’s rating</h1></div><div class="report-scroll">${starsMarkup(r)}${previous?`<p class="rating-change">${ratingChange(r,previous)}</p>`:''}<div class="mission-results">${goals.map(g=>`<span class="${g.met?'met':''}">${g.met?'✓':'○'} ${esc(g.label)}</span>`).join('')}</div><div class="metric-grid report-simple"><div class="metric"><small>Requests completed</small><b>${r.completedRequests||0}</b></div><div class="metric"><small>Customers served</small><b>${r.served||0}</b></div><div class="metric"><small>Shift profit</small><b>${money(r.profit)}</b>${r.assetSales?`<span class="profit-sales">Item sales +${money(r.assetSales)}</span>`:''}</div></div>${reviewCards(r)}</div><div class="report-actions"><button id="inspectAfter" class="paper-btn">View café</button><button id="retryDay" class="paper-btn">Retry shift</button><button id="acceptDay" class="green-btn">${state.practiceReturn?'Save replay':state.dayNumber===DAYS.length?'Finish':'Next shift'} →</button></div>`);
  $('#inspectAfter').onclick=()=>modal.close();$('#retryDay').onclick=()=>{const start=state.attemptStart,practice=state.practiceReturn,attempt=state.attempt+1;if(start){for(const k of Object.keys(state))delete state[k];Object.assign(state,JSON.parse(JSON.stringify(start)));}else{state.money-=state.liveCredited||0;}state.practiceReturn=practice;state.liveCredited=0;state.reports={previous:r};state.attempt=attempt;state.phase='adjust';state.runElapsed=0;state.runSnapshot=null;state.interventions=[];modal.close();lastSim=null;actions.renovate();changed();actions.toast('Starting funds and layout restored. Same customers, same arrivals.');};
  $('#acceptDay').onclick=()=>{if(state.practiceReturn){const saved=state.practiceReturn,h=saved.campaignHistory.find(h=>h.day===state.dayNumber),extra=Math.max(0,reward-(h.reward||0));if(goals.filter(g=>g.met).length>h.goals.filter(g=>g.met).length){h.goals=goals;h.report=r;h.reward=reward;h.earned+=extra;h.layout=JSON.parse(JSON.stringify(state.objects));}saved.money+=extra;for(const k of Object.keys(state))delete state[k];Object.assign(state,saved);modal.close();actions.renovate();changed();actions.toast('Replay record saved');return;}const amount=settleDay(state);if(amount===false)return;modal.close();actions.renovate();changed();actions.toast('Shift complete');$('#bankTakings').textContent='$0';$('#bankNote').textContent='Spendable funds shown above';if(state.phase==='campaign-complete')renderFinal();else showMission()};
 }
 function renderFinal(){const h=state.campaignHistory,last=h.at(-1)?.report;show(`<div class="report-head"><span class="eyebrow">FOUR SHIFTS COMPLETE</span><h1>Your café’s final rating</h1></div><div class="report-scroll">${starsMarkup(last)}<div class="rating-history">${h.map(d=>`<div><strong>Shift ${d.day}</strong>${starsMarkup(d.report,'Shift '+d.day+' rating')}<span>${d.goals.filter(g=>g.met).length} / ${d.goals.length} missions</span></div>`).join('')}</div></div><div class="report-actions"><button class="green-btn" id="finishWeek">View my café</button></div>`);$('#finishWeek').onclick=()=>modal.close();}
 function creditSales(report){const net=report.revenue-report.ingredientCosts,delta=net-(state.liveCredited||0);if(delta){state.money+=delta;state.liveCredited=net;$('#money').textContent=money(state.money);actions.market?.();actions.save()}}
 function live(sim){lastSim=sim;creditSales({revenue:sim.revenue,ingredientCosts:sim.costs});const progress=Math.min(1,sim.time/120),hour=8+Math.floor(progress*10);$('#simTime').textContent=(hour>12?hour-12:hour)+':00 '+(hour>=12?'PM':'AM');
  const seated=sim.parties.filter(g=>g.phase==='seated').reduce((n,g)=>n+g.size,0),waiting=sim.parties.filter(g=>['queued','toOrder','ordering','toPickup','pickupWait'].includes(g.phase)).reduce((n,g)=>n+g.size,0),served=sim.parties.filter(g=>g.served).reduce((n,g)=>n+g.size,0),lost=sim.parties.filter(g=>g.phase==='departed'&&!g.served).reduce((n,g)=>n+g.size,0);
  $('#bankTakings').textContent=money(sim.revenue);$('#bankNote').textContent='Net '+money(sim.revenue-sim.costs-30)+' · banked after the shift';$('#liveSeats').textContent=seated+' / '+sim.seats.length;$('#liveWaiting').textContent=waiting;$('#liveServed').textContent=served;$('#liveRevenue').textContent=money(sim.revenue);$('#liveLost').textContent=lost;$('#liveProfit').textContent=money(shiftProfit(sim));$('#liveProgress').max=SHIFT_MINUTES;$('#liveProgress').value=sim.time;const types=categoryResults(sim.liveTypes()),seen=Object.values(sim.liveTypes()).filter(t=>t.count),happy=seen.length?seen.reduce((n,t)=>n+t.satisfaction*t.count,0)/seen.reduce((n,t)=>n+t.count,0):null;$('#overallFace').textContent=mood(happy);$('#overallFace').setAttribute('aria-label',happy==null?'No guests yet':'Happiness '+pct(happy));$('#overallHappy').textContent=pct(happy);$('#moodFill').style.width=(happy||0)+'%';$('#seatFill').max=Math.max(1,sim.seats.length);$('#seatFill').value=seated;$('#queueDots').textContent='●'.repeat(Math.min(waiting,8))+(waiting>8?' +':'');$('#typeSatisfaction').innerHTML=types.map(t=>`<div class="guest-mood" title="${t.name}: ${pct(t.satisfaction)}"><span>${({study:'📚',social:'👥',remote:'💻'})[t.key]}</span><small>${t.key==='study'?'Study':t.key==='social'?'Social':'Work'}</small><progress style="accent-color:${t.satisfaction<35?'#d76c56':t.satisfaction<60?'#d9a940':'#69a666'}" max="100" value="${t.satisfaction||0}" aria-label="${t.name} satisfaction ${pct(t.satisfaction)}"></progress><b>${mood(t.satisfaction)}</b></div>`).join('');
  const alerts=[];$('#operationalAlerts').innerHTML=alerts.map((a,i)=>`<button data-alert="${i}" title="${esc(a.text)}" aria-label="${esc(a.text)}"><span>${({route:'🚧',wait:'⏳',noise:'🔊',groups:'🪑',sales:'🚪',bathroom:'🚻',outlets:'🔌'})[a.key]||'⚠️'}</span>${({route:'Blocked',wait:'Long wait',noise:'Too loud',groups:'No group seats',sales:'Lost sales',bathroom:'Need bathroom',outlets:'Need power'})[a.key]||'Check café'}${a.point?' ↗':''}</button>`).join('');for(const b of document.querySelectorAll('[data-alert]'))b.onclick=()=>actions.focusAlert?.(alerts[+b.dataset.alert]);$('#liveEvent').textContent=sim.rewardMessage||'Help guests before their patience runs out.';$('#liveEvent').hidden=false;$('#streakValue').textContent=sim.streak;$('#cornerStreakValue').textContent=sim.streak;const left=shiftSecondsLeft(sim.time);if($('#closingNotice'))$('#closingNotice').hidden=left>30;$('#shiftCountdown').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(sim.streakBreak&&sim.streakBreak.id!==api.lastBreak){api.lastBreak=sim.streakBreak.id;const notice=$('#streakNotice');notice.textContent='Streak of '+sim.streakBreak.count+' lost — help the next guest!';notice.hidden=false;clearTimeout(api.noticeTimer);api.noticeTimer=setTimeout(()=>notice.hidden=true,3500);}$('#tipValue').textContent=money(sim.tips);$('#repValue').textContent=Math.round(sim.reputation)+'%';$('#creditValue').textContent=money(sim.upgradeRewards);$('#comboValue').textContent=Math.min(3,1+Math.floor(sim.streak/3)*.5)+'×';
  const report=sim.results();$('#liveStay').textContent=Math.round(report.averageStay)+'m';$('#liveFlow').textContent=report.flow<40?'🔴':report.flow<70?'🟡':'🟢';renderGoals(report);
 }
 function restore(){refresh();if(state.phase==='day-report')renderReport();if(state.phase==='campaign-complete')renderFinal();if(['design','renovate','adjust'].includes(state.phase)&&state.missionSeen!==state.dayNumber)showMission()}
 $('#resultsButton').onclick=()=>state.phase==='campaign-complete'?renderFinal():renderReport();$('#pauseSim').onclick=()=>{paused=!paused;refresh()};$('#interveneSim').onclick=()=>{if(state.phase==='intervene'){requestRun();return}actions.cancel();if(lastSim)state.runElapsed=lastSim.time;state.phase='intervene';changed();actions.intervene();actions.toast('Service paused. Clear a route or improve an empty seat.');};for(const b of document.querySelectorAll('[data-speed]'))b.onclick=()=>{speed=+b.dataset.speed;refresh()};return api;
}

function reviewCards(report){return `<section class="customer-reviews"><h2>Customer reviews</h2>${(report.reviews||[]).map(r=>`<article class="customer-review"><div class="review-avatar">${esc(r.name[0])}</div><div><strong>${esc(r.name)}</strong><span class="review-type">${esc(({study:'Student',remote:'Remote worker',social:'Social visitor',casual:'Casual visitor',teens:'Student group',commuter:'Commuter',pickup:'Pickup',late:'Commuter'})[r.type]||r.type)}</span><div class="review-stars" aria-label="${r.stars} out of 5 stars"><span>${'★'.repeat(Math.round(r.stars))}${'☆'.repeat(5-Math.round(r.stars))}</span> ${r.stars.toFixed(1)} / 5</div><p>${esc(r.text)}</p></div></article>`).join('')||'<p>No customer visits this shift.</p>'}</section>`;}
